package es.educacion.orm;
import es.educacion.orm.jdbc.*; import es.educacion.orm.model.Producto; import es.educacion.orm.repository.IProductoRepository; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import java.nio.file.Path; import static org.junit.jupiter.api.Assertions.*;
class ProductoJdbcRepositoryTest { @TempDir Path temp; @Test void crudCompleto(){String url="jdbc:sqlite:"+temp.resolve("jdbc.db");DatabaseInitializer.createSchema(url);IProductoRepository r=new ProductoJdbcRepository(url);r.create(new Producto(1,"Teclado",30));assertEquals(1,r.findAll().size());assertEquals("Teclado",r.findById(1L).orElseThrow().nombre());assertTrue(r.update(new Producto(1,"Teclado mecánico",50)));assertEquals(50,r.findById(1L).orElseThrow().precio());assertTrue(r.delete(1L));assertTrue(r.findAll().isEmpty());} }